DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[SpecialOfferProduct]([SpecialOfferID],[ProductID],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SpecialOfferID],S.[ProductID],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_SpecialOfferProduct S;
INSERT stg.[SpecialOfferProduct]([SpecialOfferID],[ProductID],[rowguid],[ModifiedDate],LoadBatchID) SELECT [SpecialOfferID],[ProductID],[rowguid],[ModifiedDate],@B FROM etl_raw.[SpecialOfferProduct];
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SpecialOfferProduct','I',@Next,(SELECT R.[SpecialOfferID],R.[ProductID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[SpecialOfferProduct] R;
END ELSE BEGIN
SELECT [SpecialOfferID],[ProductID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_SpecialOfferProduct FROM ssis_flow.Delta_SpecialOfferProduct;
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SpecialOfferProduct',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[SpecialOfferID],C.[ProductID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_SpecialOfferProduct C LEFT JOIN etl_raw.[SpecialOfferProduct] R ON R.[SpecialOfferID]=C.[SpecialOfferID] AND R.[ProductID]=C.[ProductID];
DELETE R FROM etl_raw.[SpecialOfferProduct] R JOIN #CT_SpecialOfferProduct C ON R.[SpecialOfferID]=C.[SpecialOfferID] AND R.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[SpecialOfferProduct] R JOIN #CT_SpecialOfferProduct C ON R.[SpecialOfferID]=C.[SpecialOfferID] AND R.[ProductID]=C.[ProductID] JOIN ssis_flow.Delta_SpecialOfferProduct S ON S.[SpecialOfferID]=C.[SpecialOfferID] AND S.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[SpecialOfferProduct]([SpecialOfferID],[ProductID],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SpecialOfferID],S.[ProductID],S.[rowguid],S.[ModifiedDate],@B FROM #CT_SpecialOfferProduct C JOIN ssis_flow.Delta_SpecialOfferProduct S ON S.[SpecialOfferID]=C.[SpecialOfferID] AND S.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[SpecialOfferProduct] R WHERE R.[SpecialOfferID]=S.[SpecialOfferID] AND R.[ProductID]=S.[ProductID]);
INSERT stg.[SpecialOfferProduct]([SpecialOfferID],[ProductID],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[SpecialOfferID],R.[ProductID],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[SpecialOfferProduct] R JOIN #CT_SpecialOfferProduct C ON R.[SpecialOfferID]=C.[SpecialOfferID] AND R.[ProductID]=C.[ProductID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;